const token = `order:${orderId}`;
try {
  const run = await start(processOrder, [orderId, note], {
    experimental_hook: { token },
  });
  return Response.json({ runId: run.runId, started: true });
} catch (error) {
  if (!HookConflictError.is(error)) throw error;
  // Route the duplicate's payload to the run that owns the token
  const hook = await resumeHook(token, { note });
  return Response.json({ runId: hook.runId, started: false });
}
